-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- P99 approximate faction magnitudes (+8 Kromzek/+3 Kromrif), no Tormax for male trolls; retain upstream fixed 1p2g5s5c because documented coin examples vary. Despawn on delivery matches P99.
local item_lib = require("items")

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 1724 }) then
    e.self:Say("It's about time, whelp. Take your payment and leave, you're scaring away my clients.")
    e.other:Faction(430, -30, 0)
    e.other:Faction(419, 3, 0)
    e.other:Faction(448, 8, 0)
    e.other:Faction(429, 1, 0)
    e.other:AddMoneyToPP(5, 5, 2, 1, true)
    eq.depop_with_timer()
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
